(function(root){'use strict';
 const C=root.BotinCore,R=root.ENCOUNTER_DATA;
 C.TYPES.monster='Monstruo';
 const crValue=cr=>String(cr).includes('/')?String(cr).split('/').map(Number).reduce((a,b)=>a/b):Number(cr);
 const xpForCR=cr=>{const values=R.xpByCR[String(cr)];if(!values)throw Error('VD inválido.');return values.at(-1);};
 function validateMonster(m){if(!m||typeof m.cr!=='string'||!Object.hasOwn(R.xpByCR,String(m.cr))||!Number.isSafeInteger(m.xp)||m.xp<0||m.xp>1e7||m.lairXp!=null&&(!Number.isSafeInteger(m.lairXp)||m.lairXp<0||m.lairXp>1e7)||['creatureType','ac','hp','speed'].some(k=>typeof m[k]!=='string'||m[k].length>1000))throw Error('Completá el VD, PX y datos válidos del monstruo.');return m;}
 const encounterDefaults=()=>({level:3,players:4,difficulty:'moderate',maxCreatures:8,cr:'all',creatureType:'all',pool:'all',allowHigher:false,rows:[],lootMode:'none'});
 function validateEncounter(s){if(!s||!Number.isInteger(s.level)||s.level<1||s.level>20||!Number.isInteger(s.players)||s.players<1||s.players>20||!['low','moderate','high'].includes(s.difficulty)||!Number.isInteger(s.maxCreatures)||s.maxCreatures<1||s.maxCreatures>100||s.cr!=='all'&&!Object.hasOwn(R.xpByCR,s.cr)||typeof s.creatureType!=='string'||s.creatureType.length>100||typeof s.pool!=='string'||s.pool.length>200||typeof s.allowHigher!=='boolean'||!['none','personal','hoard'].includes(s.lootMode)||!Array.isArray(s.rows)||s.rows.length>100)throw Error('Configuración de encuentro inválida.');const ids=new Set();let total=0;for(const row of s.rows){if(!row||typeof row.id!=='string'||row.id.length>200||ids.has(row.id)||!Number.isInteger(row.qty)||row.qty<1||row.qty>100||typeof row.lair!=='boolean')throw Error('Enemigos inválidos.');ids.add(row.id);total+=row.qty;if(row.id.startsWith('manual:')&&(!Object.hasOwn(R.xpByCR,row.cr)||row.xp!==xpForCR(row.cr)))throw Error('VD manual inválido.');}if(total>100)throw Error('Máximo 100 criaturas por consulta.');return s;}
 function encounterBudget(level,players){const row=R.budgets.find(r=>r[0]===level);if(!row||!Number.isInteger(players)||players<1||players>20)throw Error('Nivel de 1 a 20 y cantidad de jugadores de 1 a 20.');return {low:row[1]*players,moderate:row[2]*players,high:row[3]*players};}
 function resolveRow(row,entries){const e=entries.find(e=>e.id===row.id&&e.type==='monster');if(row.id.startsWith('manual:'))return{...row,name:'Criatura · VD '+row.cr,cr:row.cr,xp:row.xp,entry:null};if(!e)return{...row,name:'Ficha no disponible',missing:true,entry:null};validateMonster(e.monster);return{...row,name:e.name,cr:e.monster.cr,xp:row.lair&&e.monster.lairXp!=null?e.monster.lairXp:e.monster.xp,entry:e};}
 function assessEncounter(s,entries){validateEncounter(s);const budget=encounterBudget(s.level,s.players),rows=s.rows.map(row=>resolveRow(row,entries)),missing=rows.some(r=>r.missing),xp=rows.reduce((sum,r)=>sum+(r.xp||0)*r.qty,0),count=rows.reduce((sum,r)=>sum+r.qty,0),difficulty=missing?'incomplete':!count?'none':xp>budget.high?'over':xp>budget.moderate?'high':xp>budget.low?'moderate':'low',warnings=[];if(rows.some(r=>!r.missing&&crValue(r.cr)>s.level))warnings.push('Hay criaturas con VD superior al nivel de los personajes.');if(count>s.players*2)warnings.push('Más de dos criaturas por personaje: revisá la cantidad de acciones enemigas.');if(missing)warnings.push('Hay fichas excluidas o no instaladas. El total de PX está incompleto.');return {budget,rows,xp,count,difficulty,remaining:budget[s.difficulty]-xp,share:xp/s.players,missing,warnings};}
 function generateEncounter(s,entries,random=Math.random){validateEncounter(s);let remaining=encounterBudget(s.level,s.players)[s.difficulty];const pool=entries.filter(e=>e.type==='monster'&&e.monster&&e.monster.xp>0&&(s.cr==='all'||String(e.monster.cr)===s.cr)&&(s.creatureType==='all'||e.monster.creatureType===s.creatureType)&&(s.allowHigher||crValue(e.monster.cr)<=s.level));pool.forEach(e=>validateMonster(e.monster));const rows=[];for(let i=0;i<s.maxCreatures;i++){let candidates=pool.filter(e=>e.monster.xp<=remaining&&(rows.length<3||rows.some(r=>r.id===e.id)));if(!candidates.length)break;const highest=Math.max(...candidates.map(e=>e.monster.xp));candidates=candidates.filter(e=>e.monster.xp>=highest/2);const e=C.sample(candidates,random),row=rows.find(r=>r.id===e.id);if(row)row.qty++;else rows.push({id:e.id,qty:1,lair:false});remaining-=e.monster.xp;}if(!rows.length)throw Error('No hay criaturas que entren en ese presupuesto con estos filtros.');return rows;}
 function encounterLoot(s,entries,tables,random=Math.random){const a=assessEncounter(s,entries);if(s.lootMode==='none')return null;if(!a.count||a.missing)throw Error('Completá los enemigos antes de generar botín.');const maxCR=Math.max(...a.rows.map(r=>crValue(r.cr)));if(s.lootMode==='hoard')return C.generate({...C.settings(),level:s.level,cr:maxCR,kind:'hoard'},entries,tables,'quick',random);const result={budget:0,coins:{po:0,pp:0,pc:0},valuables:[],items:[],warnings:[],mode:'quick',context:'Encuentro · tesoro personal por VD y cantidad'};let copper=0;for(const row of a.rows){const r=C.generate({...C.settings(),level:s.level,cr:crValue(row.cr),count:row.qty,kind:'personal'},entries,tables,'quick',random);result.budget+=r.budget;copper+=C.coinValue(r.coins);result.valuables.push(...r.valuables);result.items.push(...r.items);result.warnings.push(...r.warnings);}result.coins=C.changeIn(copper,C.BASE_COINS);return result;}
 const initial=C.initial,validate=C.validate,migrate=C.migrate;
 const validatePackage=C.validatePackage;C.validatePackage=p=>{validatePackage(p);for(const e of p.entries)if(e.type==='monster')validateMonster(e.monster);return p;};
 const ensure=d=>{if(d.encounters===undefined)d.encounters={};return d;};C.initial=()=>ensure(initial());C.migrate=d=>ensure(migrate(d));
 C.validate=input=>{const d=ensure(validate(input));if(!d.encounters||typeof d.encounters!=='object'||Array.isArray(d.encounters))throw Error('Encuentros inválidos.');for(const [key,s]of Object.entries(d.encounters)){if(!d.campaigns.some(c=>c.id===key))throw Error('Contexto de encuentro inválido.');validateEncounter(s);}for(const e of d.entries)if(e.type==='monster')validateMonster(e.monster);return d;};
 Object.assign(C,{crValue,xpForCR,validateMonster,encounterDefaults,validateEncounter,encounterBudget,assessEncounter,generateEncounter,encounterLoot});
})(typeof window==='undefined'?globalThis:window);
